-- questions
INSERT INTO questions
  (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation,
   is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code)
VALUES
  ('55555555-0009-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Bien qu''elle ___ très occupée, elle a accepté de nous recevoir. »',
   'La conjonction « bien que » est toujours suivie du subjonctif. À la 3e personne du singulier du verbe « être » au subjonctif présent, la forme est « soit ». « Est » et « était » sont des indicatifs (incompatibles avec « bien que »). « Serait » est un conditionnel (incompatible également).',
   'true', '2026-05-27 17:40:30.147221+02', '2026-05-27 17:40:30.147221+02', 'ACTIVE', NULL, NULL, 'struct_subjonctif_bien_que'),

  ('55555555-0009-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Si tu avais étudié davantage, tu ___ ton examen sans difficulté. »',
   'Avec « si + plus-que-parfait » dans la subordonnée (« avais étudié »), la principale prend obligatoirement le conditionnel passé pour exprimer une hypothèse non réalisée dans le passé → « aurais réussi ». « Réussirais » est un conditionnel présent (compatible avec « si + imparfait », pas avec « si + plus-que-parfait »). « As réussi » est un passé composé. « Réussiras » est un futur.',
   'true', '2026-05-27 17:40:30.147221+02', '2026-05-27 17:40:30.147221+02', 'ACTIVE', NULL, NULL, 'struct_hypothese_irreelle_passe'),

  ('55555555-0009-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Le projet ___ je travaille depuis six mois sera bientôt terminé. »',
   'Le verbe « travailler » se construit avec la préposition « à » (travailler à quelque chose). Pour reprendre un complément masculin singulier introduit par « à », on emploie le pronom relatif composé « auquel » (contraction de « à + lequel »). « Que » remplace un complément d''objet direct, sans préposition. « Dont » remplace un complément introduit par « de ». « Lequel », sans la contraction avec « à », ne convient pas pour reprendre un complément introduit par « à ».',
   'true', '2026-05-27 17:40:30.147221+02', '2026-05-27 17:40:30.147221+02', 'ACTIVE', NULL, NULL, 'struct_pronom_relatif_compose'),

  ('55555555-0009-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « ___ une légère hausse des prix, la fréquentation du musée reste stable. »',
   '« Malgré » est une préposition concessive qui se construit directement avec un nom ou un groupe nominal (« malgré une hausse »). « Bien que » et « quoique » sont des conjonctions qui se construisent avec un verbe au subjonctif, pas avec un nom. « Cependant » est un adverbe de liaison, qui relie deux propositions ; il ne peut pas introduire directement un groupe nominal.',
   'true', '2026-05-27 17:40:30.147221+02', '2026-05-27 17:40:30.147221+02', 'ACTIVE', NULL, NULL, 'struct_connecteur_concessif'),

  ('55555555-0010-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « ___ la nouvelle, elle a immédiatement appelé sa famille. »',
   'Pour exprimer la simultanéité ou la cause d''une action effectuée par le même sujet, on utilise le gérondif (« en » + participe présent) → « En apprenant ». Le participe présent seul (« apprenant ») marquerait davantage une cause antérieure, mais sans le « en », il devient ambigu. « Apprenu » n''existe pas (le participe passé de « apprendre » est « appris »). « Pour apprendre » exprimerait un but, ce qui n''a pas de sens ici.',
   'true', '2026-05-27 17:40:30.164849+02', '2026-05-27 17:40:30.164849+02', 'ACTIVE', NULL, NULL, 'struct_gerondif_vs_participe'),

  ('55555555-0010-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Il m''a dit qu''il ___ le lendemain. »',
   'Quand le verbe introducteur (« a dit ») est au passé, le futur du discours direct devient un conditionnel présent au discours indirect : « il viendrait ». « Vient » est un présent (compatible seulement avec un verbe introducteur au présent : « il dit qu''il vient »). « Viendra » est un futur (compatible avec un présent introducteur). « Est venu » est un passé composé, qui ne traduit pas une action future par rapport au moment où il a parlé.',
   'true', '2026-05-27 17:40:30.164849+02', '2026-05-27 17:40:30.164849+02', 'ACTIVE', NULL, NULL, 'struct_concordance_temps'),

  ('55555555-0010-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Il se peut qu''il ___ en retard à cause des embouteillages. »',
   'L''expression « il se peut que » exprime une éventualité et entraîne obligatoirement le subjonctif. À la 3e personne du singulier du verbe « être » au subjonctif présent : « soit ». « Est » et « sera » sont des indicatifs (incompatibles), « serait » est un conditionnel (également incompatible avec « il se peut que »).',
   'true', '2026-05-27 17:40:30.164849+02', '2026-05-27 17:40:30.164849+02', 'ACTIVE', NULL, NULL, 'struct_modalisation_il_se_peut'),

  ('55555555-0010-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « ___ les délais sont très courts, nous devons commencer immédiatement. »',
   '« Étant donné que » est une conjonction qui introduit une cause connue ou admise, suivie d''un verbe à l''indicatif. C''est la forme correcte ici. « Bien que » introduit une concession, suivie du subjonctif (contraire au sens et au mode). « Pour que » introduit un but, suivi du subjonctif. « Afin de » introduit un but, suivi d''un infinitif (pas d''un verbe conjugué).',
   'true', '2026-05-27 17:40:30.164849+02', '2026-05-27 17:40:30.164849+02', 'ACTIVE', NULL, NULL, 'struct_cause_avancee'),

  ('55555555-0011-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Je suis content qu''il ___ à temps hier soir. »',
   'Le verbe principal exprime un sentiment (« je suis content que »), qui déclenche le subjonctif. L''action exprimée (« arriver à temps hier soir ») est antérieure au moment où l''on parle : il faut donc le subjonctif passé → « soit arrivé » (auxiliaire « être » au subjonctif présent + participe passé au masculin singulier accordé avec « il »). « Est arrivé » est l''indicatif. « Arrive » est un subjonctif présent (incorrect pour une action passée). « Serait arrivé » est un conditionnel passé.',
   'true', '2026-05-27 17:40:30.178875+02', '2026-05-27 17:40:30.178875+02', 'ACTIVE', NULL, NULL, 'struct_subjonctif_passe'),

  ('55555555-0011-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Il est interdit ___ téléphoner pendant les réunions. »',
   'Après une tournure impersonnelle comme « il est interdit », « il est nécessaire », « il est important », on utilise la préposition « de » suivie de l''infinitif. « À » s''emploie après certains verbes (commencer à, apprendre à) mais pas avec « il est interdit ». « Que » introduirait une subordonnée avec un verbe conjugué (« il est interdit que vous téléphoniez »), pas un infinitif. « Pour » exprime un but.',
   'true', '2026-05-27 17:40:30.178875+02', '2026-05-27 17:40:30.178875+02', 'ACTIVE', NULL, NULL,
   'struct_voix_passive_impersonnelle'),

  ('55555555-0011-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « C''est à Paris ___ j''ai rencontré mon meilleur ami. »',
   'Dans la structure de mise en relief « c''est ... que/qui », on utilise « que » quand l''élément mis en relief est un complément (de lieu, de temps, d''objet). « C''est qui » se réserve à un sujet (« c''est lui qui est venu »). « Quoi » et « où » ne s''emploient pas dans cette structure : on dit « c''est à Paris que », pas « c''est à Paris où ».',
   'true', '2026-05-27 17:40:30.178875+02', '2026-05-27 17:40:30.178875+02', 'ACTIVE', NULL, NULL, 'struct_mise_en_relief'),

  ('55555555-0011-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Il ___ beau insister, je ne changerai pas d''avis. »',
   'L''expression idiomatique « avoir beau + infinitif » exprime une concession : faire un effort qui ne donne pas le résultat attendu. Elle se conjugue normalement, ici à la 3e personne du singulier du présent : « a ». « Est » et « va » sont des verbes inadaptés à cette expression figée. « Aurait » est un conditionnel (qui pourrait fonctionner dans d''autres contextes, mais pas pour une situation présente factuelle).',
   'true', '2026-05-27 17:40:30.178875+02', '2026-05-27 17:40:30.178875+02', 'ACTIVE', NULL, NULL, 'struct_avoir_beau'),

  ('55555555-0012-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « La lettre que j''ai ___ hier est arrivée ce matin. »',
   'Avec l''auxiliaire « avoir », le participe passé s''accorde avec le COD si celui-ci est placé avant le verbe. Ici, le COD « la lettre » (féminin singulier) est antéposé via le pronom relatif « que » : il faut donc accorder → « écrite ». « Écrit » serait correct si le COD était placé après le verbe ou s''il était masculin singulier. « Écrits » est un masculin pluriel, « écrites » un féminin pluriel : ni l''un ni l''autre ne correspond à « la lettre » (féminin singulier).',
   'true', '2026-05-27 17:40:30.194289+02', '2026-05-27 17:40:30.194289+02', 'ACTIVE', NULL, NULL, 'struct_accord_pp_avoir'),

  ('55555555-0012-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Remplacez : « Je donne le livre à mon frère. → Je ___ donne. »',
   'On remplace deux compléments : « le livre » (COD masculin singulier) → « le », et « à mon frère » (COI singulier) → « lui ». L''ordre est COD avant COI à la 3e personne : « le lui ». « Lui le » inverse cet ordre (incorrect). « Le leur » serait pour un COI pluriel (à eux). « La lui » mettrait un COD féminin (incorrect ici, le livre est masculin).',
   'true', '2026-05-27 17:40:30.194289+02', '2026-05-27 17:40:30.194289+02', 'ACTIVE', NULL, NULL, 'struct_double_pronom'),

  ('55555555-0012-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « La décision est ___ : le tribunal rendra son verdict dans les prochaines heures. »',
   'Le contexte (« dans les prochaines heures ») indique un événement très proche dans le temps : l''adjectif attendu est « imminente » (qui va arriver très bientôt). « Éminente » signifie remarquable, de haut rang (un professeur éminent), pas proche dans le temps. « Évidente » signifie claire, sans doute possible. « Permanente » signifie continue, durable.',
   'true', '2026-05-27 17:40:30.194289+02', '2026-05-27 17:40:30.194289+02', 'ACTIVE', NULL, NULL, 'struct_paronymes'),

  ('55555555-0012-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Mon frère adore la montagne, ___ moi, je préfère la mer. »',
   '« Alors que » introduit une opposition entre deux faits coexistants (deux préférences différentes). « Pour que » introduit un but (avec subjonctif). « Parce que » introduit une cause (la cause de quoi ?). « Si bien que » introduit une conséquence.',
   'true', '2026-05-27 17:40:30.194289+02', '2026-05-27 17:40:30.194289+02', 'ACTIVE', NULL, NULL, 'struct_opposition_alors_que'),

  ('55555555-0013-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Je ne pense pas qu''il ___ raison sur ce point. »',
   'Les verbes d''opinion (« penser », « croire », « trouver ») à la forme négative déclenchent le subjonctif (l''idée exprimée est mise en doute). « Ait » est la 3e personne du singulier du verbe « avoir » au subjonctif présent. « A » est l''indicatif présent. « Aurait » est un conditionnel. « Avait » est un imparfait. Aucun de ces trois temps n''est compatible avec « je ne pense pas que » au sens d''opinion mise en doute.',
   'true', '2026-05-27 17:40:30.209527+02', '2026-05-27 17:40:30.209527+02', 'ACTIVE', NULL, NULL,
   'struct_subjonctif_opinion_negative'),

  ('55555555-0013-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « ___ malade depuis plusieurs jours, il n''a pas pu venir travailler. »',
   'Pour exprimer une cause (état antérieur qui explique une conséquence), on emploie le participe présent « étant ». Le gérondif « en étant » exprimerait plutôt une simultanéité (« en étant malade, il continuait à travailler »), ce qui n''est pas le sens ici. « Été » est un participe passé, qui aurait besoin d''un auxiliaire pour fonctionner. « Soit » est un subjonctif présent, inadapté en tête de phrase ici.',
   'true', '2026-05-27 17:40:30.209527+02', '2026-05-27 17:40:30.209527+02', 'ACTIVE', NULL, NULL, 'struct_participe_present_cause'),

  ('55555555-0013-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Ce plat ___ avec un vin blanc sec, traditionnellement. »',
   'Le verbe pronominal « se servir » a ici un sens passif (= être servi). À la 3e personne du singulier du présent : « se sert ». « Sert » sans pronom réfléchi ne convient pas (un plat ne sert pas activement). « S''est servi » est un passé composé, qui changerait le sens (description d''une habitude générale demande le présent). « Se servait » est un imparfait, qui suggérerait une habitude révolue.',
   'true', '2026-05-27 17:40:30.209527+02', '2026-05-27 17:40:30.209527+02', 'ACTIVE', NULL, NULL, 'struct_pronominal_sens_passif'),

  ('55555555-0013-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez : « Sophie adore le théâtre ; ___, elle n''apprécie pas du tout l''opéra. »',
   'Le contexte oppose deux préférences contraires (théâtre = positif, opéra = négatif) : on attend un connecteur d''opposition. « En revanche » exprime exactement cette opposition. « En effet » introduit une explication ou une confirmation. « Par conséquent » introduit une conséquence. « En outre » ajoute une idée dans le même sens.',
   'true', '2026-05-27 17:40:30.209527+02', '2026-05-27 17:40:30.209527+02', 'ACTIVE', NULL, NULL, 'struct_connecteur_en_revanche'),

  ('55555555-0023-0000-0000-000000000017', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez avec le mode correct : Je suis vraiment heureux que tu ___ venir à mon anniversaire.',
   'Après une expression de sentiment comme « être heureux que », on utilise le subjonctif. Le subjonctif présent de « pouvoir » à la 2e personne singulier est « puisses ». La réponse C est correcte. « Peux » est l''indicatif présent, jamais après « être heureux que ». « Pourras » est le futur, écarté par la règle du subjonctif. « Pourrais » est le conditionnel, lui aussi incompatible. Les trois distracteurs sont des formes valides du verbe mais pas dans ce contexte.',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL, 'struct_subjonctif_sentiment'),

  ('55555555-0023-0000-0000-000000000018', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez avec le temps qui respecte la concordance : Elle m''a dit qu''elle ___ son examen la veille.',
   'En discours indirect au passé, un passé composé devient plus-que-parfait : « avait passé » (action antérieure à « a dit »). La réponse C est correcte. « A passé » est le passé composé : il faudrait que les deux actions soient au même niveau temporel, ce qui n''est pas le cas. « Passait » est l''imparfait : décrit une habitude ou une action en cours, pas une action accomplie avant. « Passerait » est le conditionnel, utilisé pour le futur dans le passé, mais « la veille » indique le passé.',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL, 'struct_concordance_temps'),

  ('55555555-0023-0000-0000-000000000019', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez avec le pronom relatif correct : C''est l''auteur ___ je vous ai parlé hier soir.',
   'Le verbe « parler » se construit avec « de » : « parler DE quelqu''un ». Le pronom relatif qui reprend un complément introduit par « de » est « dont ». La réponse B est correcte. « Que » remplace un COD, or « parler » prend un COI. « À qui » s''utilise avec un verbe à préposition « à » (« parler à quelqu''un » est aussi possible, mais le contexte « je vous ai parlé » + d''auteur favorise le sens de « parler de »). « Auquel » s''utilise pour un référent introduit par « à » (« je pense à cet auteur → auquel »).',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL, 'struct_pronom_relatif_dont'),

  ('55555555-0023-0000-0000-000000000020', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez avec l''accord correct du verbe « poser » : Tes clés ? Je les ai ___ sur la table de la cuisine.',
   'Avec l''auxiliaire « avoir », le participe passé s''accorde avec le COD si celui-ci est antéposé. « Les » remplace « tes clés » (féminin pluriel), antéposé au verbe → « posées ». La réponse C est correcte. « Posé » est la forme par défaut (masculin singulier) : oubli total d''accord. « Posés » accorde au masculin pluriel : faux genre. « Posée » accorde au féminin singulier : faux nombre. Ce point est un classique du B2 : il exige d''identifier le pronom COD et son genre/nombre.',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL,
   'struct_accord_participe_cod_antepose'),

  ('55555555-0023-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Transformez à la voix passive : Le directeur a signé la lettre.',
   'À la voix passive, le COD devient sujet, et l''auxiliaire « être » se met au temps du verbe actif (passé composé → « a été »). Le participe passé s''accorde avec le nouveau sujet : « la lettre » (féminin singulier) → « signée ». La réponse C est correcte. « La lettre a signé par le directeur » est une transformation erronée : le sujet ne peut pas « signer » lui-même. « La lettre est signée par le directeur » est au présent (l''action serait actuelle). « La lettre était signée par le directeur » est à l''imparfait (action passée habituelle ou état).',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL, 'struct_voix_passive'),

  ('55555555-0023-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez l''hypothèse irréelle au passé : Si nous ___ plus tôt, nous n''aurions pas raté le train.',
   'L''hypothèse irréelle au passé suit la structure « si + plus-que-parfait » → « conditionnel passé ». Avec « partir » : « si nous étions partis ». La réponse C est correcte. « Partions » est l''imparfait : utilisé pour l''hypothèse irréelle au présent (« si nous partions plus tôt, nous ne raterions pas »). « Étions parti » oublie l''accord pluriel sur « partis ». « Sommes partis » est le passé composé, jamais utilisé après « si » d''hypothèse.',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL, 'struct_hypothese_irreelle_passe'),

  ('55555555-0023-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez avec le connecteur logique qui convient : Il a beaucoup travaillé ; ___, il a réussi son concours haut la main.',
   'La deuxième proposition exprime la conséquence positive de la première. « Par conséquent » est le connecteur de conséquence le plus adapté à ce registre. La réponse B est correcte. « Cependant » exprime l''opposition : contraire au sens voulu. « En revanche » exprime aussi le contraste, incompatible. « Pour autant » introduit une nuance restrictive (« et pourtant »), opposée à la logique de la phrase. Le piège B2 : « par conséquent » et « en revanche » sont tous deux des connecteurs soutenus, mais expriment des relations opposées.',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL, 'struct_connecteurs_logiques'),

  ('55555555-0023-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'B2', 'STRUCTURE',
   'Complétez avec le mode correct : Je ne crois pas que cette solution ___ la meilleure pour résoudre le problème.',
   'Après un verbe d''opinion à la forme négative (« ne pas croire que »), on utilise le subjonctif. Le subjonctif présent de « être » à la 3e personne singulier est « soit ». La réponse B est correcte. « Est » est l''indicatif : utilisé uniquement après l''affirmation (« je crois que c''est la meilleure »). « Sera » est le futur de l''indicatif, incompatible avec le doute exprimé. « Serait » est le conditionnel, utilisé dans des constructions différentes. Ce point distingue le B2 du B1 : le subjonctif après doute/opinion négative.',
   'true', '2026-05-27 17:40:30.278936+02', '2026-05-27 17:40:30.278936+02', 'ACTIVE', NULL, NULL,
   'struct_subjonctif_opinion_negative');

-- choices
INSERT INTO choices
  (id, question_id, label, is_correct, display_order)
VALUES
  ('4ad6bf33-f63a-4ed9-b3ba-c6bd257844a9', '55555555-0009-0000-0000-000000000021', 'est', 'false', '1'),
  ('9ed2c917-f07d-4b10-ab1b-14cc356a1bae', '55555555-0009-0000-0000-000000000021', 'soit', 'true', '2'),
  ('3f58cf7d-bc26-4cf3-8395-072e53b7e84a', '55555555-0009-0000-0000-000000000021', 'était', 'false', '3'),
